import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"自悲","description":"","frontmatter":{"title":"自悲","date":"2026-11-24T00:00:00.000Z","seq":35,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"东方朔","source_book":"楚辞","prev":{"text":"七谏·怨思","link":"/blogs/楚辞/七谏·怨思.html"},"next":{"text":"哀命","link":"/blogs/楚辞/哀命.html"}},"headers":[],"relativePath":"blogs/楚辞/自悲.md","filePath":"blogs/楚辞/自悲.md"}'),o={name:"blogs/楚辞/自悲.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="自悲" tabindex="-1">自悲 <a class="header-anchor" href="#自悲" aria-label="Permalink to &quot;自悲&quot;">​</a></h1><p class="poem-meta">先秦 · 东方朔　·　七谏</p><div class="poem"><p class="poem-stanza">居愁懃其谁告兮，独永思而忧悲。</p><p class="poem-stanza">内自省而不惭兮，操愈坚而不衰。</p><p class="poem-stanza">隐三年而无决兮，岁忽忽其若颓。</p><p class="poem-stanza">怜余身不足以卒意兮，冀一见而复归。</p><p class="poem-stanza">哀人事之不幸兮，属天命而委之咸池。</p><p class="poem-stanza">身被疾而不闲兮，心沸热其若汤。</p><p class="poem-stanza">冰炭不可以相并兮，吾固知乎命之不长。</p><p class="poem-stanza">哀独苦死之无乐兮，惜予年之未央。</p><p class="poem-stanza">悲不反余之所居兮，恨离予之故乡。</p><p class="poem-stanza">鸟兽惊而失群兮，犹高飞而哀鸣。</p><p class="poem-stanza">狐死必首丘兮，夫人孰能不反其真情？</p><p class="poem-stanza">故人疏而日忘兮，新人近而俞好。</p><p class="poem-stanza">莫能行于杳冥兮，孰能施于无报？</p><p class="poem-stanza">苦众人之皆然兮，乘回风而远游。</p><p class="poem-stanza">凌恆山其若陋兮，聊愉娱以忘忧。</p><p class="poem-stanza">悲虚言之无实兮，苦众口之铄金。</p><p class="poem-stanza">过故乡而一顾兮，泣歔欷而霑衿。</p><p class="poem-stanza">厌白玉以为面兮，怀琬琰以为心。</p><p class="poem-stanza">邪气入而感内兮，施玉色而外淫。</p><p class="poem-stanza">何青云之流澜兮，微霜降之蒙蒙。</p><p class="poem-stanza">徐风至而徘徊兮，疾风过之汤汤。</p><p class="poem-stanza">闻南籓乐而欲往兮，至会稽而且止。</p><p class="poem-stanza">见韩众而宿之兮，问天道之所在？</p><p class="poem-stanza">借浮云以送予兮，载雌霓而为旌。</p><p class="poem-stanza">驾青龙以驰骛兮，班衍衍之冥冥。</p><p class="poem-stanza">忽容容其安之兮，超慌忽其焉如？</p><p class="poem-stanza">苦众人之难信兮，愿离群而远举。</p><p class="poem-stanza">登峦山而远望兮，好桂树之冬荣。</p><p class="poem-stanza">观天火之炎炀兮，听大壑之波声。</p><p class="poem-stanza">引八维以自道兮，含沆瀣以长生。</p><p class="poem-stanza">居不乐以时思兮，食草木之秋实。</p><p class="poem-stanza">饮菌若之朝露兮，构桂木而为室。</p><p class="poem-stanza">杂橘柚以为囿兮，列新夷与椒桢。</p><p class="poem-stanza">鹍鹤孤而夜号兮，哀居者之诚贞。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
